# Helper for backtracking/DFS

def getHappyString(n, k):
    res = []

    # Backtracking function
    def dfs(curr):
        if len(res) >= k:
            return  # early pruning; only need first k
        if len(curr) == n:
            res.append(curr)
            return
        for ch in 'abc':
            # Don't repeat previous character
            if not curr or curr[-1] != ch:
                dfs(curr + ch)

    dfs("")
    if len(res) < k:
        return ""
    return res[k-1]  # 0-indexed
